(function(){'use strict';const $=s=>document.querySelector(s),owner=KashierData.userId(),key='kashier.daily-close.v1.'+owner,M=DailyClose;let epoch=0,busy=false,pending=null,current=null,saved=null,blocked=false;const active=()=>owner&&KashierData.loggedIn()&&KashierData.userId()===owner,status=s=>$('#close-status').textContent=s,fmt=v=>new Intl.NumberFormat('en-US').format(BigInt(v));
function controls(){for(const k of ['day','actual','note'])$('#close-'+k).disabled=busy||blocked||!!pending||(k!=='day'&&!!saved);$('#close-ack').disabled=busy||blocked||!!saved;$('#close-load').disabled=busy||blocked;$('#close-save').disabled=busy||blocked||!current||!!saved||!$('#close-ack').checked;$('#close-print').disabled=$('#close-csv').disabled=!saved||busy;}
function clear(){current=null;saved=null;$('#close-paper').hidden=true;$('#close-details').replaceChildren();$('#close-preview').textContent='';$('#close-ack').checked=false;controls();}
function render(r){saved=r;$('#close-paper').hidden=false;const rows=[['ناسنامەی داخستن',r.id],['ڕۆژ — کاتی بەغدا',r.day],['باڵانسی ڕاپۆرت',fmt(r.expected)+' دینار'],['پارەی ژمێردراو',fmt(r.actual)+' دینار'],['جیاوازی',fmt(r.difference)+' دینار'],['هۆکار',r.note||'—'],['کاتی تۆمارکردن',r.created_at]];$('#close-details').replaceChildren();for(const [label,value] of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;$('#close-details').append(dt,dd);}controls();}
function resolve(r){if(pending){M.row(r,owner,pending.day,r.id===pending.id?pending:undefined);sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('داواکاریی تەواوبوو لە پاشەکەوت پاک نەکرایەوە.');pending=null;}render(r);}
async function account(){if(!active())throw Error('هەژمارەکە گۆڕاوە.');const a=await KashierData.getAccount();if(!active()||a.id!==owner)throw Error('ناسنامەی هەژمار پشتڕاست نەکرایەوە.');}
async function load(){if(busy||blocked)return;const life=++epoch,d=$('#close-day').value;clear();busy=true;controls();try{M.day(d);await account();const v=await KashierData.getDailyClosePreview(d);if(life!==epoch||!active())return;M.preview(v,owner,d);current=v;$('#close-preview').textContent='باڵانسی کۆتایی ڕاپۆرت: '+fmt(v.report.cash.closing)+' دینار';if(v.close){resolve(v.close);status(v.close.source_hash===v.snapshot_hash?'داخستنە پارێزراوەکە پیشان درا.':'ڕاپۆرتی ئێستا لە بەڵگەی داخستنی پارێزراو گۆڕاوە؛ پشکنینی خاوەن پێویستە.');}else status(pending?'ئەنجامێک هێشتا نییە؛ هەمان داواکاری دەتوانرێت دووبارە بنێردرێت.':'بڕی ژمێردراو و هۆکار بنووسە و پشتڕاست بکەرەوە.');}catch(e){if(life===epoch){clear();status(e.message);}}finally{busy=false;controls();}}
$('#close-load').addEventListener('click',load);$('#close-day').addEventListener('input',()=>{epoch++;clear();$('#close-actual').value=$('#close-note').value='';});$('#close-ack').addEventListener('change',controls);
$('#close-save').addEventListener('click',async()=>{if(busy||blocked||!current||saved||!$('#close-ack').checked)return;const life=epoch;busy=true;controls();try{await account();if(life!==epoch)return;let p=pending;if(!p){p=M.payload({owner,id:crypto.randomUUID(),day:current.day,actual:DailyCashCount.parse($('#close-actual').value),note:$('#close-note').value.trim(),hash:current.snapshot_hash},owner);if(BigInt(p.actual)!==BigInt(current.report.cash.closing)&&!p.note)throw Error('بۆ کەمی یان زیادەی پارە هۆکار بنووسە.');const value=JSON.stringify(p);sessionStorage.setItem(key,value);if(sessionStorage.getItem(key)!==value)throw Error('داواکاری پاشەکەوت نەکرا؛ هیچ تۆمارێک نەنێردرا.');pending=p;}if(life!==epoch||!active())return;const result=await KashierData.postDailyClose(p.id,p.day,p.actual,p.note,p.hash);if(life!==epoch||!active())return;const r=M.receipt(result,owner,p);resolve(r);status('داخستنی ڕۆژ تۆمار کرا؛ هیچ مامەڵەی پارە دروست نەکرا.');}catch(e){if(life===epoch){if(pending&&['close_snapshot_changed','close_difference_reason_required','close_completed_day_required','close_invalid_request','close_day_already_closed'].includes(e.saleCode)){try{sessionStorage.removeItem(key);if(sessionStorage.getItem(key)===null)pending=null;}catch{}}status(e.message+' بۆ پشکنینی ئەنجام دوگمەی نوێکردنەوە دابگرە.');}}finally{busy=false;controls();}});
$('#close-print').addEventListener('click',()=>{if(active()&&saved)window.print();else clear();});$('#close-csv').addEventListener('click',()=>{if(!active()){clear();return;}if(!saved)return;const url=URL.createObjectURL(new Blob([M.csv(saved,owner)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='daily-cash-close-'+saved.day+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});window.addEventListener('beforeprint',()=>{if(!active())clear();});window.addEventListener('pagehide',()=>{epoch++;clear();$('#close-actual').value=$('#close-note').value='';status('');});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
try{if(!active()){location.replace('auth.html?next=daily-close.html');return;}const raw=sessionStorage.getItem(key);if(raw){pending=M.payload(JSON.parse(raw),owner);$('#close-day').value=pending.day;$('#close-actual').value=pending.actual;$('#close-note').value=pending.note;}else{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),today=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');$('#close-day').value=new Date(Date.parse(today+'T00:00:00Z')-86400000).toISOString().slice(0,10);}load();}catch(e){blocked=true;clear();status(e.message);}
})();
